using UnityEngine;
namespace MetaPort.Games.FirstSteps { public class FirstStepsManager : MonoBehaviour { public GameObject[] tutorialObjects; void Awake(){ Debug.Log("[FirstSteps] Hand tracking tutorial"); var go=GameObject.CreatePrimitive(PrimitiveType.Cube); go.name="GrabCube_Tutorial"; go.transform.SetParent(transform,false); go.transform.localPosition=Vector3.forward*1f; go.transform.localScale=Vector3.one*0.2f; go.AddComponent<Rigidbody>().useGravity=false; var mat=new Material(Shader.Find("MetaPort/Icon3D")); mat.SetColor("_BaseColor", Color.yellow); go.GetComponent<Renderer>().material=mat; } } }
